import numpy as np
from scipy.optimize import least_squares
d=np.array([[float(v.replace(',','.')) for v in line.split()] for line in open('graphene.dat') if line.strip()])
x,y=d[:,0],d[:,1]
o=np.argsort(x); x,y=x[o],y[o]

def lor(x,x0,g,a): return a*g*g/((x-x0)**2+g*g)

def model(p,x):
    # laser + G + 2D + offset
    return p[9]+sum(lor(x,p[3*i],abs(p[3*i+1])+1e-9,p[3*i+2]) for i in range(3))

for lo,hi in [(15500,19500),(15800,19300),(16000,19200),(16500,19200),(15500,20000)]:
    m=(x>lo)&(x<hi); xr,yr=x[m],y[m]
    p0=[19100,300,70000, 17330,100,1000, 16250,150,2000, 1000]
    try:
        res=least_squares(lambda p: model(p,xr)-yr,p0,max_nfev=50000,loss='soft_l1',f_scale=300)
        print('window',lo,hi,'cost',res.cost)
        for i,n in enumerate(['laser','G','2D']):
            print(' ',n,res.x[3*i:3*i+3])
        print(' offset',res.x[9])
    except Exception as e: print('err',e)
