import numpy as np
from scipy.optimize import curve_fit

d=np.array([[float(v.replace(',','.')) for v in line.split()] for line in open('graphene.dat') if line.strip()])
x,y=d[:,0],d[:,1]
o=np.argsort(x); x,y=x[o],y[o]

def lor(x,x0,g,a,c0,c1): return c0+c1*(x-x0)+a*g*g/((x-x0)**2+g*g)
def gau(x,x0,s,a,c0,c1): return c0+c1*(x-x0)+a*np.exp(-0.5*((x-x0)/s)**2)

print("2D region windows")
for lo,hi in [(15800,16700),(15900,16600),(16000,16550),(15700,16800),(15500,17000)]:
    m=(x>lo)&(x<hi); xr,yr=x[m],y[m]
    for fun,p0 in [(lor,[16200,150,2000,16000,10]),(gau,[16200,100,2000,16000,10])]:
        try:
            popt,pcov=curve_fit(fun,xr,yr,p0=p0,maxfev=100000)
            perr=np.sqrt(np.diag(pcov))
            print(f" {lo}-{hi} {fun.__name__}: x0={popt[0]:.2f}±{perr[0]:.2f} g={popt[1]:.2f}±{perr[1]:.2f} a={popt[2]:.1f} c0={popt[3]:.1f} c1={popt[4]:.2f}")
