import numpy as np
from scipy.optimize import curve_fit

d=np.array([[float(v.replace(',','.')) for v in line.split()] for line in open('graphene.dat') if line.strip()])
x,y=d[:,0],d[:,1]
s=1e7/x
o=np.argsort(s); s,y=s[o],y[o]

def lor_const(s,x0,g,a,c): return c+a*g*g/((s-x0)**2+g*g)
def lor_lin(s,x0,g,a,c,m): return c+m*(s-x0)+a*g*g/((s-x0)**2+g*g)
def gau_const(s,x0,sig,a,c): return c+a*np.exp(-0.5*((s-x0)/sig)**2)

def run(name, windows):
    print('\n===',name,'===')
    for lo,hi in windows:
        m=(s>lo)&(s<hi); sr,yr=s[m],y[m]
        for fun,p0 in [(lor_const,[1580 if name=='G' else 2670,10 if name=='G' else 25,5000,6000 if name=='G' else 1800]),(gau_const,[1580 if name=='G' else 2670,10 if name=='G' else 25,5000,6000 if name=='G' else 1800])]:
            try:
                popt,pcov=curve_fit(fun,sr,yr,p0=p0,maxfev=200000)
                perr=np.sqrt(np.diag(pcov))
                print(f" {lo}-{hi} {fun.__name__}: x0={popt[0]:.3f}±{perr[0]:.3f} g={popt[1]:.3f}±{perr[1]:.3f} a={popt[2]:.1f}±{perr[2]:.1f} c={popt[3]:.1f}±{perr[3]:.1f}")
            except Exception as e: print('err',e)
        if name=='G':
            try:
                popt,pcov=curve_fit(lor_lin,sr,yr,p0=[1580,10,5000,6000,0],maxfev=200000)
                perr=np.sqrt(np.diag(pcov))
                print(f" {lo}-{hi} lor_lin: x0={popt[0]:.3f}±{perr[0]:.3f} g={popt[1]:.3f}±{perr[1]:.3f} a={popt[2]:.1f}±{perr[2]:.1f} c={popt[3]:.1f} m={popt[4]:.3f}")
            except Exception as e: print('err',e)

run('G',[(1500,1660),(1520,1640),(1540,1620),(1550,1610),(1530,1650),(1490,1670)])
run('2D',[(2500,2850),(2550,2800),(2580,2760),(2600,2740),(2620,2720),(2450,2900)])
