   popt,_=curve_fit(fun,sr,yr,p0=p0,maxfev=300000)
   r=fun(sr,*popt)-yr
   print(f" {lo}-{hi} {fun.__name__}: "+" ".join(f"{v:.3f}" for v in popt)+f" rmse={np.sqrt(np.mean(r*r)):.2f}")
